// #6a993d791a95398b11e1fb6e — шаг «התנגדות» черновика: «מהספרייה» (6 типовых) или «נוסח חופשי». Кейс TPL-009.
// QA-данные: черновик «QA-N15 טיוטה מתבנית (biz)» у testim. Ничего не сохраняется: смена радио запускает
// автосохранение (rpc/save_simulation) — все изменяющие запросы к /rest/v1 и /functions/v1 обрываются,
// в конце черновик сверяется с исходным. Сохранение/одобрение/генерацию AI тест не нажимает.
import * as path from 'path';
import { test, expect } from '@playwright/test';
import { openWithApi } from '../support/api';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const SIMULATION_ID = '871160e4-193a-4393-af44-8b62a2934c09';
const LIBRARY = [
  'אין לי זמן לזה עכשיו',
  'אנחנו כבר עובדים עם ספק אחר',
  'המחיר גבוה מדי',
  'זה לא רלוונטי לנו כרגע',
  'צריך לחשוב על זה ולהתייעץ',
  'תשלחו לי חומר במייל',
];

test.describe('Шаблоны симуляций — шаг «התנגדות» в черновике (#6a993d791a95398b11e1fb6e)', () => {
  test('шаг «התנגדות»: «מהספרייה» (6 типовых) или «נוסח חופשי» @desktop @data #6a993d791a95398b11e1fb6e', async ({ page }) => {
    const blocked: string[] = [];
    await page.route(/\/(rest|functions)\/v1\//, (route) => {
      const m = route.request().method();
      if (m === 'GET' || m === 'HEAD' || m === 'OPTIONS') return route.continue();
      blocked.push(`${m} ${new URL(route.request().url()).pathname}`);
      return route.abort();
    });

    const api = await openWithApi(page, `/simulations/${SIMULATION_ID}`);
    const read = async () => {
      const res = await api.get(`simulations?select=*&id=eq.${SIMULATION_ID}`);
      expect(res.ok(), `чтение черновика: ${res.status()}`).toBeTruthy();
      const rows = (await res.json()) as Record<string, unknown>[];
      expect(rows, 'черновик QA-N15 не найден у business').toHaveLength(1);
      return rows[0];
    };
    const before = await read();

    await expect(page.getByText('QA-N15 טיוטה מתבנית (biz)').first()).toBeVisible();
    await page.getByRole('button', { name: /03\s*התנגדות/ }).click();
    await page.waitForURL(/step=objection/);

    // Источник: AC3 — «בוחר פריט מהספרייה או מזין התנגדות חופשית».
    const source = page.getByRole('group', { name: 'מקור ההתנגדות' });
    const library = source.getByRole('radio', { name: 'מהספרייה' });
    const free = source.getByRole('radio', { name: 'נוסח חופשי' });
    await expect(library).toBeChecked();
    await expect(free).not.toBeChecked();

    // Источник: FL-13 — 6 типовых возражений библиотеки.
    const select = page.getByLabel('התנגדות מהספרייה');
    await expect(select).toBeVisible();
    const options = (await select.locator('option').allTextContents()).map((t) => t.trim()).filter((t) => t !== 'בחירת התנגדות…');
    expect([...options].sort()).toEqual([...LIBRARY].sort());

    await free.check();
    await expect(free).toBeChecked();
    await expect(select).toHaveCount(0);
    const text = page.getByLabel('ההתנגדות המרכזית');
    await expect(text).toBeVisible();
    await expect(text).toBeEditable();

    await library.check();
    await expect(library).toBeChecked();
    await expect(page.getByLabel('התנגדות מהספרייה')).toBeVisible();

    // Черновик не изменился (автосохранение оборвано).
    test.info().annotations.push({ type: 'blocked-writes', description: blocked.join(' · ') || 'нет' });
    expect(blocked.every((b) => b.endsWith('/rpc/save_simulation')), `неожиданные изменяющие запросы: ${blocked.join(', ')}`).toBeTruthy();
    expect(await read()).toEqual(before);
  });
});
